body.query:
  query Programme($key: String!) {
    resource(id: $key) {
      ...ResourceRedirectDetails
      ... on Programme {
        ...ProgrammePage
      }
    }
  }

fragment ResourceRedirectDetails on Resource {
  __typename
  ... on Article {
    id
    title
    urlAlias
  }
  ... on Composition {
    id
    maybeTitle: title
    urlAlias
  }
  ... on DataUse {
    id
    title
  }
  ... on Document {
    id
    title
  }
  ... on MeetingEvent {
    id
    title
  }
  ... on News {
    id
    title
  }
  ... on Programme {
    id
    title
  }
  ... on GbifProject {
    id
    title
  }
  ... on Tool {
    id
    title
  }
}

fragment ProgrammePage on Programme {
  title
  excerpt
  blocks {
    ...BlockItemDetails
  }
  ...ProgrammeFundingBanner
}

fragment BlockItemDetails on BlockItem {
  __typename
  ... on HeaderBlock {
    id
    ...HeaderBlockDetails
  }
  ... on FeatureBlock {
    id
    ...FeatureBlockDetails
  }
  ... on FeaturedTextBlock {
    id
    ...FeaturedTextBlockDetails
  }
  ... on CarouselBlock {
    id
    ...CarouselBlockDetails
  }
  ... on MediaBlock {
    id
    ...MediaBlockDetails
  }
  ... on MediaCountBlock {
    id
    ...MediaCountBlockDetails
  }
  ... on CustomComponentBlock {
    id
    ...CustomComponentBlockDetails
  }
  ... on TextBlock {
    id
    ...TextBlockDetails
  }
}

fragment HeaderBlockDetails on HeaderBlock {
  __typename
  title
  summary
  hideTitle
  primaryImage {
    ...ArticleBanner
  }
}

fragment ArticleBanner on AssetImage {
  description
  title
  file {
    url
    details {
      image {
        width
        height
      }
    }
    normal: thumbor(width: 1200, height: 500)
    mobile: thumbor(width: 800, height: 400)
  }
}

fragment FeatureBlockDetails on FeatureBlock {
  __typename
  maxPerRow
  title
  hideTitle
  body
  backgroundColour
  features {
    __typename
    ... on Feature {
      id
      title
      comment
      url
      primaryImage {
        ...ProseCardImg
      }
    }
    ... on News {
      id
      title
      optionalImg: primaryImage {
        ...ProseCardImg
      }
    }
    ... on DataUse {
      id
      title
      optionalImg: primaryImage {
        ...ProseCardImg
      }
    }
    ... on MeetingEvent {
      id
      title
      start
      end
      allDayEvent
      optionalImg: primaryImage {
        ...ProseCardImg
      }
    }
  }
}

fragment ProseCardImg on AssetImage {
  file {
    mobile: thumbor(width: 500, height: 400)
  }
  title
  description
}

fragment FeaturedTextBlockDetails on FeaturedTextBlock {
  __typename
  id
  title
  hideTitle
  body
  backgroundColour
  primaryImage {
    file {
      url
    }
  }
}

fragment CarouselBlockDetails on CarouselBlock {
  __typename
  id
  title
  body
  backgroundColour
  features {
    __typename
    ... on MediaBlock {
      ...MediaBlockDetails
    }
    ... on MediaCountBlock {
      ...MediaCountBlockDetails
    }
  }
}

fragment MediaBlockDetails on MediaBlock {
  __typename
  id
  mediaTitle: title
  body
  optionalImg: primaryImage {
    file {
      url
    }
    title
    description
  }
  reverse
  subtitle
  backgroundColour
  roundImage
  callToAction {
    label
    url
  }
}

fragment MediaCountBlockDetails on MediaCountBlock {
  __typename
  id
  mediaTitle: title
  body
  optionalImg: primaryImage {
    file {
      mobile: thumbor(width: 500, height: 400)
    }
    title
    description
  }
  reverse
  subtitle
  titleCountPart
  backgroundColour
  roundImage
  callToAction {
    label
    url
  }
}

fragment CustomComponentBlockDetails on CustomComponentBlock {
  id
  componentType
  title
  width
  backgroundColour
  settings
}

fragment TextBlockDetails on TextBlock {
  title
  body
  hideTitle
  id
  backgroundColour
}

fragment ProgrammeFundingBanner on Programme {
  __typename
  fundingOrganisations {
    ...FundingOrganisationDetails
  }
}

fragment FundingOrganisationDetails on FundingOrganisation {
  id
  title
  url
  logo {
    title
    file {
      url
    }
  }
}
